pub fn command(args: &[&str]) -> Result<String, String> {
    match args {
        ["list"] => Ok("list".to_owned()),
        ["add", title] if !title.trim().is_empty() => {
            Ok(format!("add:{}", title.trim()))
        }
        _ => Err("usage".to_owned()),
    }
}

fn main() {
    assert_eq!(
        command(&["add", "  learn Rust 🦀  "]),
        Ok("add:learn Rust 🦀".to_owned()),
        "case 1"
    );
    assert_eq!(command(&[]), Err("usage".to_owned()), "case 2");
    assert_eq!(
        command(&["add", ""]),
        Err("usage".to_owned()),
        "case 3"
    );
    assert_eq!(
        command(&["list", "extra"]),
        Err("usage".to_owned()),
        "case 4"
    );
    assert_eq!(command(&["list"]), Ok("list".to_owned()), "case 5");
    println!("worked example passed");
}

